using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using StockManagement.Data;using StockManagement.Models;using StockManagement.Services;
namespace StockManagement.Controllers;[Authorize(Roles=Roles.Admin+","+Roles.Manager)] public class CategoriesController:Controller{readonly ApplicationDbContext _db;readonly AuditService _audit;public CategoriesController(ApplicationDbContext db,AuditService audit){_db=db;_audit=audit;}public IActionResult Index()=>View(_db.Categories.Include(x=>x.Products).OrderBy(x=>x.Name).ToList());public IActionResult Create()=>View(new Category());[HttpPost,ValidateAntiForgeryToken]public IActionResult Create(Category c){if(!ModelState.IsValid)return View(c);_db.Categories.Add(c);_db.SaveChanges();_audit.Add("Category","Create",$"Created {c.Name}",User.Identity?.Name??"System");return RedirectToAction(nameof(Index));}public IActionResult Edit(int id){var c=_db.Categories.Find(id);return c==null?NotFound():View(c);}[HttpPost,ValidateAntiForgeryToken]public IActionResult Edit(Category c){if(!ModelState.IsValid)return View(c);var e=_db.Categories.Find(c.Id);if(e==null)return NotFound();e.Name=c.Name;e.Description=c.Description;_db.SaveChanges();return RedirectToAction(nameof(Index));}[HttpPost,ValidateAntiForgeryToken]public IActionResult Delete(int id){var c=_db.Categories.Find(id);if(c!=null){_db.Categories.Remove(c);try{_db.SaveChanges();}catch{TempData["Error"]="Category is in use.";}}return RedirectToAction(nameof(Index));}}
